import type { PDFDocument, PDFImage } from 'pdf-lib';
import { loadImageToCanvas, canvasToBlob } from '@/lib/image/convert';

// Above this, embedding every page in the main thread starts to feel like
// it's hung the tab — reject early with a clear reason instead.
export const MAX_IMAGES = 60;
export const MAX_BYTES_PER_IMAGE = 25 * 1024 * 1024;

function isJpegFile(file: File): boolean {
  return file.type === 'image/jpeg' || /\.jpe?g$/i.test(file.name);
}

/** Embeds an image into the PDF. At quality 100 ("original"), prefers a direct JPEG
 * embed with no re-encoding, falling back to decoding onto a canvas and embedding as
 * lossless PNG for anything else (or for JPEGs pdf-lib can't read directly, e.g.
 * CMYK-encoded ones). Below 100, every image is uniformly recompressed as JPEG at that
 * quality — recompressing only the ones that were already JPEG would leave the slider
 * changing some pages' size but not others, which is confusing. */
async function embedImage(
  pdfDoc: PDFDocument,
  file: File,
  quality: number,
): Promise<{ image: PDFImage; width: number; height: number }> {
  if (quality >= 100 && isJpegFile(file)) {
    try {
      const bytes = await file.arrayBuffer();
      const image = await pdfDoc.embedJpg(bytes);
      return { image, width: image.width, height: image.height };
    } catch {
      // Falls through to the canvas path below.
    }
  }

  const canvas = await loadImageToCanvas(file);

  if (quality >= 100) {
    const blob = await canvasToBlob(canvas, 'image/png');
    const bytes = await blob.arrayBuffer();
    const image = await pdfDoc.embedPng(bytes);
    return { image, width: canvas.width, height: canvas.height };
  }

  const q = Math.min(1, Math.max(0.01, quality / 100));
  const blob = await canvasToBlob(canvas, 'image/jpeg', q);
  const bytes = await blob.arrayBuffer();
  const image = await pdfDoc.embedJpg(bytes);
  return { image, width: canvas.width, height: canvas.height };
}

export interface BuildPdfProgress {
  index: number;
  total: number;
}

// A stable id decouples a picked image's identity from both its array
// position (which changes on reorder) and its File's own fields (which
// collide if the same file gets picked twice) — dnd-kit and React list keys
// both need identity that survives reordering.
export interface PickedImage {
  id: string;
  file: File;
}

/** Builds a single PDF with one A4 page per image, in the given order — built
 * entirely in memory in the browser, never uploaded anywhere. Every page is the
 * same fixed A4 size regardless of the source image's resolution; each image is
 * scaled to fit within the page (preserving aspect ratio, no cropping) and centered.
 * quality: 1-100, see embedImage — 100 keeps each image at its original fidelity. */
export async function buildPdfFromImages(
  files: File[],
  quality: number,
  onProgress?: (progress: BuildPdfProgress) => void,
): Promise<Blob> {
  if (files.length > MAX_IMAGES) {
    throw new Error(`That's ${files.length} images — the limit is ${MAX_IMAGES} per PDF.`);
  }

  // pdf-lib is ~400kB — imported dynamically so it's only downloaded once the
  // user actually generates a PDF, not just from visiting the page.
  const { PDFDocument, PageSizes } = await import('pdf-lib');
  const [A4_WIDTH, A4_HEIGHT] = PageSizes.A4;

  const pdfDoc = await PDFDocument.create();

  for (let i = 0; i < files.length; i++) {
    onProgress?.({ index: i + 1, total: files.length });

    const { image, width, height } = await embedImage(pdfDoc, files[i], quality);
    const page = pdfDoc.addPage([A4_WIDTH, A4_HEIGHT]);

    const scale = Math.min(A4_WIDTH / width, A4_HEIGHT / height);
    const drawWidth = width * scale;
    const drawHeight = height * scale;
    page.drawImage(image, {
      x: (A4_WIDTH - drawWidth) / 2,
      y: (A4_HEIGHT - drawHeight) / 2,
      width: drawWidth,
      height: drawHeight,
    });
  }

  const bytes = await pdfDoc.save();
  return new Blob([bytes], { type: 'application/pdf' });
}
