import type { DragEvent, FC, KeyboardEvent } from 'react';
import { useRef, useState } from 'react';
import { toast } from 'sonner';
import { UploadCloud, Plus } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';
import { MAX_BYTES_PER_IMAGE, MAX_IMAGES } from '@/lib/pdf/fromImages';

interface UploadBoxProps {
  count: number;
  onAdd: (files: File[]) => void;
  /** Once images are already added, the full-size dropzone gives way to this
   * small button so the image grid can move up and take the space instead. */
  compact?: boolean;
}

// This tool is multi-file, so users need to keep adding images after the
// first one — hence `compact`, not a one-shot swap to a "file selected" card.
const UploadBox: FC<UploadBoxProps> = ({ count, onAdd, compact }) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFiles = (fileList: FileList | null) => {
    const picked = Array.from(fileList ?? []);
    if (picked.length === 0) return;

    const room = MAX_IMAGES - count;
    if (room <= 0) {
      toast.error(`You've already added the max of ${MAX_IMAGES} images`);
      return;
    }

    const accepted: File[] = [];
    for (const file of picked) {
      if (!file.type.startsWith('image/')) {
        toast.error(`${file.name} isn't an image — skipped`);
        continue;
      }
      if (file.size > MAX_BYTES_PER_IMAGE) {
        toast.error(`${file.name} is too large (max ${formatBytes(MAX_BYTES_PER_IMAGE)}) — skipped`);
        continue;
      }
      accepted.push(file);
    }

    if (accepted.length > room) {
      toast.warning(`Only added ${room} of ${accepted.length} images — ${MAX_IMAGES} max per PDF`);
    }

    if (accepted.length > 0) onAdd(accepted.slice(0, room));
  };

  const sharedHandlers = {
    onClick: () => inputRef.current?.click(),
    onDragOver: (e: DragEvent) => {
      e.preventDefault();
      setIsDragging(true);
    },
    onDragLeave: () => setIsDragging(false),
    onDrop: (e: DragEvent) => {
      e.preventDefault();
      setIsDragging(false);
      handleFiles(e.dataTransfer.files);
    },
    role: 'button' as const,
    tabIndex: 0,
    onKeyDown: (e: KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === ' ') inputRef.current?.click();
    },
  };

  const input = (
    <input
      ref={inputRef}
      type="file"
      accept="image/*"
      multiple
      className="hidden"
      onChange={(e) => {
        handleFiles(e.target.files);
        e.target.value = '';
      }}
    />
  );

  if (compact) {
    return (
      <div
        {...sharedHandlers}
        aria-label="Add more images"
        className={`inline-flex items-center gap-1.5 px-3.5 py-2 rounded-full text-sm font-medium border cursor-pointer transition-colors shrink-0 ${
          isDragging
            ? 'border-accent/60 bg-accent/5 text-foreground'
            : 'border-border text-foreground/80 hover:text-foreground hover:border-accent/40'
        }`}
      >
        {input}
        <Plus className="w-4 h-4" />
        Add images
      </div>
    );
  }

  return (
    <div
      {...sharedHandlers}
      className={`glass-panel flex flex-col items-center justify-center gap-3 py-10 px-6 text-center cursor-pointer transition-colors ${
        isDragging ? 'border-accent/60 bg-accent/5' : 'hover:border-border'
      }`}
    >
      {input}
      <UploadCloud className="w-8 h-8 text-muted-foreground/50" />
      <div>
        <p className="text-sm font-medium text-foreground">Drop images here, or click to browse</p>
        <p className="text-xs text-muted-foreground mt-1">
          JPG, PNG, WebP, and more · up to {MAX_IMAGES} images, {formatBytes(MAX_BYTES_PER_IMAGE)} each
        </p>
      </div>
    </div>
  );
};

export default UploadBox;
