import type { FC } from 'react';
import { useEffect, useState } from 'react';
import {
  DndContext,
  type DragEndEvent,
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  SortableContext,
  arrayMove,
  rectSortingStrategy,
  sortableKeyboardCoordinates,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { X, ImageIcon } from 'lucide-react';
import type { PickedImage } from '@/lib/pdf/fromImages';

interface ImageGridProps {
  images: PickedImage[];
  onReorder: (images: PickedImage[]) => void;
  onRemove: (id: string) => void;
}

const SortableThumb: FC<{ image: PickedImage; index: number; total: number; onRemove: () => void }> = ({
  image,
  index,
  total,
  onRemove,
}) => {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: image.id });
  const [url, setUrl] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    setFailed(false);
    const objectUrl = URL.createObjectURL(image.file);
    setUrl(objectUrl);
    return () => URL.revokeObjectURL(objectUrl);
  }, [image.file]);

  return (
    <div
      ref={setNodeRef}
      style={{ transform: CSS.Transform.toString(transform), transition }}
      className={`flex flex-col items-center gap-1.5 ${isDragging ? 'z-10 opacity-90' : ''}`}
    >
      {/* The remove button is a sibling of the drag surface, not a descendant —
          dnd-kit's {...attributes} make the drag surface a role="button" element,
          and a <button> nested inside another interactive element is invalid
          (axe: nested-interactive) and confuses assistive tech. */}
      <div className="group relative w-full">
        <div
          {...attributes}
          {...listeners}
          aria-label={`Reorder ${image.file.name}, page ${index + 1} of ${total}`}
          className="w-full aspect-square rounded-lg overflow-hidden border border-border bg-background/50 cursor-grab active:cursor-grabbing touch-none select-none"
        >
          {url && !failed ? (
            <img
              src={url}
              alt=""
              onError={() => setFailed(true)}
              draggable={false}
              className="w-full h-full object-cover pointer-events-none"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center">
              <ImageIcon className="w-6 h-6 text-muted-foreground" />
            </div>
          )}
        </div>

        <button
          type="button"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={onRemove}
          aria-label={`Remove ${image.file.name}`}
          className="absolute top-1 right-1 p-1 rounded-full bg-background/80 text-muted-foreground opacity-0 group-hover:opacity-100 focus-visible:opacity-100 hover:text-foreground transition-opacity"
        >
          <X className="w-3.5 h-3.5" />
        </button>
      </div>
      <span className="text-xs font-mono text-muted-foreground">{index + 1}</span>
    </div>
  );
};

// Horizontal grid instead of a top-to-bottom list — reads the page order at a
// glance and uses far less vertical space for more than a couple of images.
// Reordering is drag-and-drop (grab cursor on hover) instead of buttons.
const ImageGrid: FC<ImageGridProps> = ({ images, onReorder, onRemove }) => {
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 4 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );

  if (images.length === 0) return null;

  const ids = images.map((img) => img.id);

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const from = ids.indexOf(String(active.id));
    const to = ids.indexOf(String(over.id));
    if (from === -1 || to === -1) return;
    onReorder(arrayMove(images, from, to));
  };

  return (
    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <SortableContext items={ids} strategy={rectSortingStrategy}>
        <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 gap-3">
          {images.map((image, index) => (
            <SortableThumb
              key={image.id}
              image={image}
              index={index}
              total={images.length}
              onRemove={() => onRemove(image.id)}
            />
          ))}
        </div>
      </SortableContext>
    </DndContext>
  );
};

export default ImageGrid;
